package trust

import (
	_ "embed"
	"errors"
	"fmt"
	"sync"
)

// releaseFloorJSON is generated by the release pipeline from the latest
// published floor statement.
//
//go:embed release_floor.json
var releaseFloorJSON []byte

// ReleaseFloor is the binary release floor (release_floor.json).
type ReleaseFloor struct {
	Bundles           map[string]int64
	MinProfileVersion int64
}

var releaseFloor = sync.OnceValues(func() (ReleaseFloor, error) { return parseReleaseFloor(releaseFloorJSON) })

// EmbeddedReleaseFloor returns the compiled release floor. A parse failure is
// returned on every call, so callers fail closed.
func EmbeddedReleaseFloor() (ReleaseFloor, error) { return releaseFloor() }

func parseReleaseFloor(data []byte) (ReleaseFloor, error) {
	var f struct {
		Bundles           map[string]int64 `json:"bundles"`
		MinProfileVersion *int64           `json:"min_profile_version"`
	}
	if err := strictUnmarshal(data, nil, &f); err != nil {
		return ReleaseFloor{}, fmt.Errorf("release floor: %w", err)
	}
	if f.Bundles == nil || f.MinProfileVersion == nil || *f.MinProfileVersion < 0 || len(f.Bundles) > maxFloorBundles {
		return ReleaseFloor{}, errors.New("release floor: bundles and min_profile_version >= 0 are required")
	}
	for id, v := range f.Bundles {
		if !floorIDRE.MatchString(id) || v < 1 {
			return ReleaseFloor{}, fmt.Errorf("release floor: bundles entry %q: %d invalid", id, v)
		}
	}
	return ReleaseFloor{Bundles: f.Bundles, MinProfileVersion: *f.MinProfileVersion}, nil
}

// Pin is the org pin of an org-specific build: that org is always governed.
type Pin struct {
	OrgID string
}

// parseOrgPin parses org_pin.json ({org_id, governed: true}). A pin cannot
// say governed false: any other content is an error.
func parseOrgPin(data []byte) (*Pin, error) {
	var p struct {
		OrgID    string `json:"org_id"`
		Governed *bool  `json:"governed"`
	}
	if err := strictUnmarshal(data, names("org_id", "governed"), &p); err != nil {
		return nil, fmt.Errorf("org pin: %w", err)
	}
	if !floorIDRE.MatchString(p.OrgID) || p.Governed == nil || !*p.Governed {
		return nil, errors.New("org pin: want {org_id, governed: true}")
	}
	return &Pin{OrgID: p.OrgID}, nil
}

// Floors are the run's minimum sources besides the trust state and env.
// Statement counts only when VerifyFloor built it for OrgID and Mode. Profile
// holds the selected profile's bundles[].min_version, Manifest the
// min_bundle_version of verified manifests.
type Floors struct {
	OrgID         string
	Mode          string
	Governed      bool // org pin, signed profile or COMPLIANCETF_GOVERNED=true
	FloorRequired bool // the profile requires fetched bundles
	Release       ReleaseFloor
	Statement     *Floor
	Profile       map[string]int64
	Manifest      map[string]int64
}

func (f Floors) statement() (*Floor, error) {
	st := f.Statement
	if st != nil && (st.mode == "" || st.mode != f.Mode || st.OrgID != f.OrgID) {
		st = nil // not a VerifyFloor result for this run
	}
	if st == nil && (f.Governed || f.FloorRequired) {
		return nil, fmt.Errorf("Org floor for %s unavailable: governed runs need a signed floor statement (floor_mode %s).", f.OrgID, f.Mode) //nolint:staticcheck // spec text
	}
	return st, nil
}

// EffectiveBundleMin is the minimum version of bundleID for this run: the max
// of the state, release floor, floor statement, profile, manifests and env.
func (s State) EffectiveBundleMin(bundleID string, f Floors) (int64, error) {
	st, err := f.statement()
	if err != nil {
		return 0, err
	}
	var fromStatement int64
	if st != nil {
		fromStatement = st.Bundles[bundleID]
	}
	return s.MinBundleVersion(bundleID, f.Release.Bundles[bundleID], fromStatement, f.Profile[bundleID], f.Manifest[bundleID])
}

// EffectiveProfileMin is the minimum profile version of f.OrgID for this run.
func (s State) EffectiveProfileMin(f Floors) (int64, error) {
	st, err := f.statement()
	if err != nil {
		return 0, err
	}
	var fromStatement int64
	if st != nil {
		fromStatement = st.MinProfileVersion
	}
	return s.MinProfileVersion(f.OrgID, f.Release.MinProfileVersion, fromStatement)
}
